package org.zipp.ai.infrastructure.adapter.repository.evaluation;
import org.springframework.stereotype.Repository;
import org.zipp.ai.domain.agent.model.valobj.evaluation.intake.*;
import org.zipp.ai.domain.agent.service.evaluation.intake.ITraceToEvalStore;
import org.zipp.ai.infrastructure.dao.ITraceToEvalMapper;
import org.zipp.ai.infrastructure.dao.po.evaluation.*;
import javax.annotation.Resource;
import java.util.Optional;
import java.util.List;
@Repository
public class TraceToEvalRepository implements ITraceToEvalStore {
 @Resource private ITraceToEvalMapper mapper;
 public Optional<EvalCaseCandidate> findCandidate(String id){return Optional.ofNullable(mapper.selectCandidate(id)).map(this::candidate);}
 public Optional<EvalCaseCandidate> findCandidateBySourceRunAndFailureFamily(String r,String f){return Optional.ofNullable(mapper.selectCandidateBySource(r,f)).map(this::candidate);}
 public List<EvalCaseCandidate> listCandidates(EvalCandidateStatus s,String risk,int limit,int offset){return mapper.selectCandidates(s==null?null:s.name(),risk,limit,offset).stream().map(this::candidate).toList();}
 public void insertCandidate(EvalCaseCandidate v){mapper.insertCandidate(candidatePo(v));} public void updateCandidateStatus(String id,EvalCandidateStatus s){mapper.updateCandidateStatus(id,s.name());}
 public void mergeCandidateModelEvidence(String id,String version,Double confidence,List<String> evidence,String summary){mapper.mergeCandidateModelEvidence(id,version,confidence,com.alibaba.fastjson.JSON.toJSONString(evidence),summary);}
 public void insertReview(EvalCaseReview v){EvalCaseReviewPO p=new EvalCaseReviewPO();p.setId(v.getId());p.setCandidateId(v.getCandidateId());p.setReviewer(v.getReviewer());p.setDecision(v.getDecision());p.setReason(v.getReason());p.setReviewedAt(java.util.Date.from(v.getReviewedAt()));mapper.insertReview(p);}
 public Optional<EvalCaseDraft> findLatestDraft(String candidateId){return Optional.ofNullable(mapper.selectLatestDraft(candidateId)).map(p->com.alibaba.fastjson.JSON.parseObject(p.getDraftJson(),EvalCaseDraft.class));}
 public void insertDraft(EvalCaseDraft v){EvalCaseDraftPO p=new EvalCaseDraftPO();p.setId(v.getId());p.setCandidateId(v.getCandidateId());p.setDraftJson(com.alibaba.fastjson.JSON.toJSONString(v));p.setSanitizerVersion(v.getSanitizerVersion());p.setModelVersion(v.getModelVersion());p.setCreatedAt(java.util.Date.from(v.getCreatedAt()));mapper.insertDraft(p);}
 public void upsertCaseHealth(EvalCaseHealthRecord v){EvalCaseHealthPO p=new EvalCaseHealthPO();p.setCaseId(v.getCaseId());p.setCaseVersion(v.getCaseVersion());p.setBaselineReproduced(v.getBaselineReproduced());p.setHealthStatus(v.getHealthStatus());p.setSummary(v.getSummary());p.setUpdatedAt(java.util.Date.from(v.getUpdatedAt()));mapper.upsertCaseHealth(p);}
 public void insertSemanticMinerRun(SemanticMinerRun v){mapper.insertSemanticMinerRun(semanticRunPo(v));}
 public void updateSemanticMinerRun(SemanticMinerRun v){mapper.updateSemanticMinerRun(semanticRunPo(v));}
 public Optional<SemanticMinerRun> findSemanticMinerRun(String id){return Optional.ofNullable(mapper.selectSemanticMinerRun(id)).map(this::semanticRun);}
 public List<SemanticMinerRun> listSemanticMinerRuns(int limit){return mapper.selectSemanticMinerRuns(limit).stream().map(this::semanticRun).toList();}
 public void insertLineage(EvalCaseLineage v){EvalCaseLineagePO p=new EvalCaseLineagePO();p.setPromotionId(v.getPromotionId());p.setCaseId(v.getCaseId());p.setDatasetVersion(v.getDatasetVersion());p.setReviewer(v.getReviewer());p.setApprovedAt(java.util.Date.from(v.getApprovedAt()));p.setSanitizerVersion(v.getSanitizerVersion());p.setOrigin(v.getOrigin());mapper.insertLineage(p);}
 private EvalCaseCandidate candidate(EvalCaseCandidatePO p){return EvalCaseCandidate.builder().id(p.getId()).sourceRunId(p.getSourceRunId()).sourceSpanId(p.getSourceSpanId()).sourcePhase(p.getSourcePhase()).sourceAgentId(p.getSourceAgentId()).failureFamily(p.getFailureFamily()).ruleId(p.getRuleId()).evidenceSummary(p.getEvidenceSummary()).risk(p.getRisk()).discoveredAt(p.getDiscoveredAt().toInstant()).policyVersion(p.getPolicyVersion()).status(EvalCandidateStatus.valueOf(p.getStatus())).createdBy(p.getCreatedBy()).detectionSource(org.apache.commons.lang3.StringUtils.defaultIfBlank(p.getDetectionSource(),"RULE_DETECTED")).modelVersion(p.getModelVersion()).modelConfidence(p.getModelConfidence()).modelEvidence(p.getModelEvidenceJson()==null?List.of():com.alibaba.fastjson.JSON.parseArray(p.getModelEvidenceJson(),String.class)).build();}
 private EvalCaseCandidatePO candidatePo(EvalCaseCandidate v){EvalCaseCandidatePO p=new EvalCaseCandidatePO();p.setId(v.getId());p.setSourceRunId(v.getSourceRunId());p.setSourceSpanId(v.getSourceSpanId());p.setSourcePhase(v.getSourcePhase());p.setSourceAgentId(v.getSourceAgentId());p.setFailureFamily(v.getFailureFamily());p.setRuleId(v.getRuleId());p.setEvidenceSummary(v.getEvidenceSummary());p.setRisk(v.getRisk());p.setDiscoveredAt(java.util.Date.from(v.getDiscoveredAt()));p.setPolicyVersion(v.getPolicyVersion());p.setStatus(v.getStatus().name());p.setCreatedBy(v.getCreatedBy());p.setDetectionSource(org.apache.commons.lang3.StringUtils.defaultIfBlank(v.getDetectionSource(),"RULE_DETECTED"));p.setModelVersion(v.getModelVersion());p.setModelConfidence(v.getModelConfidence());p.setModelEvidenceJson(com.alibaba.fastjson.JSON.toJSONString(v.getModelEvidence()));return p;}
 private SemanticMinerRun semanticRun(SemanticMinerRunPO p){return SemanticMinerRun.builder().id(p.getId()).status(SemanticMinerRunStatus.valueOf(p.getStatus())).samplingPolicy(SemanticSamplingPolicy.valueOf(p.getSamplingPolicy())).requestedLimit(p.getRequestedLimit()).sampledCount(p.getSampledCount()).analyzedCount(p.getAnalyzedCount()).candidateCount(p.getCandidateCount()).errorCount(p.getErrorCount()).estimatedCostUsd(p.getEstimatedCostUsd()).modelVersion(p.getModelVersion()).sanitizerVersion(p.getSanitizerVersion()).availabilityReason(p.getAvailabilityReason()).createdBy(p.getCreatedBy()).createdAt(instant(p.getCreatedAt())).startedAt(instant(p.getStartedAt())).completedAt(instant(p.getCompletedAt())).build();}
 private SemanticMinerRunPO semanticRunPo(SemanticMinerRun v){SemanticMinerRunPO p=new SemanticMinerRunPO();p.setId(v.getId());p.setStatus(v.getStatus().name());p.setSamplingPolicy(v.getSamplingPolicy().name());p.setRequestedLimit(v.getRequestedLimit());p.setSampledCount(v.getSampledCount());p.setAnalyzedCount(v.getAnalyzedCount());p.setCandidateCount(v.getCandidateCount());p.setErrorCount(v.getErrorCount());p.setEstimatedCostUsd(v.getEstimatedCostUsd());p.setModelVersion(v.getModelVersion());p.setSanitizerVersion(v.getSanitizerVersion());p.setAvailabilityReason(v.getAvailabilityReason());p.setCreatedBy(v.getCreatedBy());p.setCreatedAt(date(v.getCreatedAt()));p.setStartedAt(date(v.getStartedAt()));p.setCompletedAt(date(v.getCompletedAt()));return p;}
 private java.time.Instant instant(java.util.Date value){return value==null?null:value.toInstant();}
 private java.util.Date date(java.time.Instant value){return value==null?null:java.util.Date.from(value);}
}
